    if (!void_vm_readable(base, 4)) return 0;
    const uint32_t args[] = {base, 0, 0x00F272C0u, 0x00F323A8u, 0};
    return void_call_guest(0x00D119FCu, 5, args, 0) == screen;
}

static int camera_town_prepare(uint32_t screen)
{
