    uint32_t table = town ? 0x00E2A64Cu : kind == 1 ? 0x00E1DA84u : 0x00E230E4u;
    uint32_t operator_offset = town ? 0x368u : kind == 1 ? 0x3A4u : 0x568u;
    if (!void_vm_readable(screen, operator_offset + 4) ||
        MEM32(screen) != table) return 0;
