    uint32_t camera = MEM32(screen + 0x9C), hand = MEM32(screen + operator_offset);
    if (!void_vm_readable(hand, town ? 0x178u : 0x14Cu)) return 0;
    if (town && (MEM32(hand) != 0x00E449BCu || MEM32(hand + 0x144) != camera)) return 0;
