        !isfinite(position[7]) || !isfinite(position[8])) return 0;
    uint32_t args[2] = {camera_scratch + 0x6B0, 1};
    memcpy(GPTR(args[0]), position, sizeof position);
    if (town) {
        void_call_guest_this(set, hand, 2, args);
