    /* The native town manual initializer keeps its original CameraPos here. */
    float pose[10];
    memcpy(pose, GPTR(screen + 0x394), sizeof pose);
    if (!isfinite(pose[0]) || pose[0] <= 0) return 0;
    return void_touch_camera_pose(screen, 2, pose, 1, 1);
