    if (!void_vm_readable(placement, 160) || MEM32(placement) != 0x00E202DCu) goto invalid;
    uint32_t army = MEM32(placement + 0x24);
    if (!void_vm_readable(army, 12) || MEM32(army) != 0x00E17BCCu) goto invalid;
    uint32_t combat = MEM32(army + 8);
