        float w = MEMF(viewport), h = MEMF(viewport + 4);
        if (isfinite(w) && isfinite(h) && w > 0 && h > 0 && fov > 0 && fov < 180 &&
            (w / h > 1366.0f / 768.0f || (hud && framing.ratio != 1))) {
